from pathlib import Path
for root in ['experiments/e1','experiments/e2','experiments/e3','experiments/e4']:
 for p in Path(root).rglob('*.md'):
  txt=p.read_text(errors='replace')
  lines=txt.splitlines()
  hits=[i for i,t in enumerate(lines) if ('normal quasitrace' in t.lower() or 'order continuous' in t.lower() or 'order-continu' in t.lower() or 'existing suprem' in t.lower())]
  for i in hits:
   print('\n',p, '\n', '\n'.join(lines[max(0,i-2):i+3]))

